from itertools import combinations, permutations
from pysat.solvers import Glucose3
from pysat.formula import CNF
from pysat.card import CardEnc, EncType

n = 19
num_colors = 3

def edge_var(u, v):
    return u * n + v + 1

def color_var(v, c):
    return n * n + v * num_colors + c + 1

def ev(x, y):
    return edge_var(min(x,y), max(x,y))

def get_canonical_cycle(cycle):
    cyc_list = list(cycle)
    min_val = min(cyc_list)
    idx = cyc_list.index(min_val)
    rotated = cyc_list[idx:] + cyc_list[:idx]
    if rotated[1] > rotated[-1]:
        rotated = [rotated[0]] + rotated[1:][::-1]
    return tuple(rotated)

cnf = CNF()

# 1. Each vertex gets at least one color
for v in range(n):
    cnf.append([color_var(v, c) for c in range(num_colors)])

# 2. Adjacent vertices get different colors
for u in range(n):
    for v in range(u+1, n):
        for c in range(num_colors):
            cnf.append([-ev(u,v), -color_var(u,c), -color_var(v,c)])

# 3. No cycles of length 3,4,5,6
for length in [3, 4, 5, 6]:
    for verts in combinations(range(n), length):
        seen = set()
        for perm in permutations(verts[1:]):
            cycle = (verts[0],) + perm
            key = get_canonical_cycle(cycle)
            if key not in seen:
                seen.add(key)
                edges_cyc = [ev(key[i], key[(i+1)%length]) for i in range(length)]
                cnf.append([-e for e in edges_cyc])

print(f"Clauses after girth constraints: {len(cnf.clauses)}")

# 4. At least 29 edges
all_edge_vars = [ev(u,v) for u in range(n) for v in range(u+1, n)]
card_clauses = CardEnc.atleast(lits=all_edge_vars, bound=29, encoding=EncType.seqcounter)
for clause in card_clauses.clauses:
    cnf.append(clause)

print(f"Total clauses: {len(cnf.clauses)}")
print("Solving...")

solver = Glucose3()
solver.append_formula(cnf)
result = solver.solve()
print(f"SAT result: {result}")

if result:
    model = solver.get_model()
    edges = []
    for u in range(n):
        for v in range(u+1, n):
            var = ev(u, v)
            if model[var-1] > 0:
                edges.append((u, v))
    print(f"Number of edges: {len(edges)}")
    print(f"Edges: {edges}")
